/* ======================================================================
   Philosophy test: six scored axes (like the other online philosophy quizzes), each answer carries
   effects from -2 to +2. PHIL_EFFECTS[i][j] = what option j of question i does.
   E: Duty (-) to Outcomes (+)   K: Faith and gut (-) to Evidence (+)   M: Spiritual mind (-) to Physical mind (+)
   V: Objective values (-) to Relative values (+)   C: Confident (-) to Sceptical (+)   W: Free will (-) to Determinism (+)
   ====================================================================== */
const PHIL_AXES = {
  E: ['Duty', 'Outcomes'], K: ['Faith and gut', 'Evidence'], M: ['Spiritual mind', 'Physical mind'],
  V: ['Objective values', 'Relative values'], C: ['Confident', 'Sceptical'], W: ['Free will', 'Determinism'],
};
const PHIL_EFFECTS = [
  [{E:2}, {E:1}, {E:-2}, {V:2}],
  [{E:-2}, {E:-1}, {E:1}, {E:2}],
  [{E:-2,V:-1}, {E:-1}, {E:1}, {E:2,V:1}],
  [{K:2}, {K:1}, {K:-1}, {K:-2}],
  [{M:2}, {M:1}, {M:-1}, {C:1}],
  [{C:-2}, {C:-1}, {C:1}, {C:2}],
  [{V:-2}, {V:-1}, {V:1}, {V:2}],
  [{W:-2}, {W:-1}, {W:1}, {W:2}],
  [{K:2}, {K:1}, {C:1}, {K:-2}],
  [{V:-2,K:1}, {V:-1}, {V:1}, {V:2}],
  [{M:-2}, {M:-1}, {M:2}, {C:2}],
  [{K:-2}, {K:-1}, {K:1}, {K:2}],
  [{V:-2}, {}, {V:1}, {V:2}],
  [{C:-2}, {C:-1}, {C:1}, {C:2}],
  [{E:-2,W:-1}, {E:-1}, {E:1}, {E:2,W:1}],
];
// Ideal profiles (0 to 100 on each axis) for the six philosophy types; you get the nearest one.
const PHIL_TYPES = {
  Empiricist:    { E:50, K:90, M:80, V:50, C:60, W:60 },
  Rationalist:   { E:50, K:85, M:60, V:15, C:20, W:50 },
  Utilitarian:   { E:90, K:70, M:70, V:50, C:40, W:60 },
  Stoic:         { E:25, K:60, M:50, V:25, C:40, W:70 },
  Existentialist:{ E:40, K:40, M:40, V:85, C:60, W:20 },
  Skeptic:       { E:50, K:50, M:60, V:70, C:90, W:50 },
};

/* PhilPapers-survey-style position questions: "which is closest to your view?" on the classic topics
   (mind, God, knowledge, what makes actions right, personal identity, science). */
PHIL_QUESTIONS.push(
  { q: 'The mind-body problem: what is the relationship between the mind and the brain?', tag: 'pp', opts: ['Physicalism: the mind is nothing but brain activity (identity theory)', 'Functionalism: the mind is what the brain does, and can\'t be reduced to its chemistry, though it is still physical', 'Property dualism: the brain is physical, but conscious experience is a non-physical property it gives rise to (Chalmers)', 'Substance dualism: the mind is a non-physical soul that interacts with the body (Descartes)'] },
  { q: 'Philosophy of religion: does God exist?', tag: 'pp', opts: ['Theism: a personal God exists, who created the world and cares for it', 'Deism or pantheism: something divine exists, but not a personal God who intervenes (Spinoza)', 'Agnosticism: we cannot know whether God exists, so we should suspend judgement', 'Atheism: there is no God'] },
  { q: 'Rationalism or empiricism: where does our knowledge ultimately come from?', tag: 'pp', opts: ['Empiricism: all knowledge comes from experience and observation (Locke, Hume)', 'Kant\'s synthesis: experience supplies the content of knowledge, and reason supplies its structure', 'Rationalism: the most important truths are known by reason and intuition alone (Plato, Descartes)', 'Revelation: some truths can only be known through faith or divine revelation (Augustine)'] },
  { q: 'Normative ethics: which theory comes closest to explaining what makes an action right?', tag: 'pp', opts: ['Deontology: right actions follow moral duties and rules, whatever the consequences (Kant)', 'Virtue ethics: right actions are what a person of good character would do (Aristotle)', 'Consequentialism: right actions produce the best overall outcomes (Bentham, Mill)', 'Contractualism: right actions follow principles no one could reasonably reject (Scanlon)'] },
  { q: 'Personal identity: what makes you the same person over a lifetime?', tag: 'pp', opts: ['Being the same living organism, with the same body and brain (animalism)', 'Continuity of memory and personality (the psychological view, Locke)', 'An immaterial soul that persists through every change (Descartes, Swinburne)', 'Nothing. There is no lasting self, only a stream of experiences (Hume\'s bundle theory, the Buddha)'] },
  { q: 'Scientific realism: do our best scientific theories describe reality as it really is?', tag: 'pp', opts: ['Yes. The success of science would be a miracle if its theories weren\'t approximately true (Hilary Putnam)', 'In outline. Science gets the structure of reality right, even when the details change (structural realism)', 'We don\'t need to say. Theories are tools for predicting what we observe, not pictures of hidden reality (instrumentalism, van Fraassen)', 'No. Science is shaped by its time and culture, one paradigm among others (Kuhn, Feyerabend)'] },
);
PHIL_EFFECTS.push(
  [{M:2}, {M:1}, {M:-1}, {M:-2}],
  [{M:-2,K:-1}, {M:-1}, {M:1,C:1}, {M:2,K:1}],
  [{K:2}, {K:1}, {K:-1}, {K:-2}],
  [{E:-2}, {E:-1}, {E:2}, {V:1}],
  [{M:2}, {M:1}, {M:-2}, {C:1,M:1}],
  [{K:2,C:-1}, {K:1}, {C:1}, {C:2,V:1}],
);

/* More philosophy scenarios (to 45 questions in all), each with its effects on the six axes. */
PHIL_QUESTIONS.push(
  { q: "Kant's murderer at the door: a murderer asks where your friend is hiding. Kant said you still must not lie. Was he right?", tag: 'sc', opts: ["Yes. Lying is always wrong, and you answer for your duty, not for the murderer's choices", "Partly. You may refuse to answer or stay silent, but lying itself remains wrong", "No. Saving a life clearly outweighs the duty of honesty; the consequences decide", "No, and the case shows moral rules are only conventions, to be dropped when they don't serve us"] },
  { q: "The transplant case (Judith Jarvis Thomson): a surgeon could secretly kill one healthy patient and use his organs to save five. Should she?", tag: 'sc', opts: ["Never. It uses a person merely as a means, violating his dignity (Kant's formula of humanity)", "No, though the numbers matter. You may not intend harm as a means, even for a good end (double effect)", "Yes, in principle. Five lives outweigh one, and our horror at it is a bias (strict utilitarianism)", "There is no fact of the matter. Our clashing intuitions show ethics is a matter of feeling"] },
  { q: "The deathbed promise: you promised a dying friend to give their money to one charity, but another would do far more good. What should you do?", tag: 'sc', opts: ["Keep it. A promise creates a duty that holds even when breaking it would do more good (W.D. Ross)", "Keep it, with regret. The duty of fidelity outweighs the gain, but the lost good still counts", "Break it. Act utilitarianism: do whatever produces the most good", "Keep to its purpose, not its letter: give where your friend would have wanted, had they known the facts"] },
  { q: "Nozick's experience machine: a machine could give you a lifetime of perfect experiences that feel completely real. Would you plug in for good?", tag: 'sc', opts: ["Yes. Hedonism: pleasure is the only thing good in itself, and the machine delivers it (Bentham)", "Probably. If it feels identical, it's hard to say what would be missing", "No. We want to actually do things and be a certain kind of person, not just have experiences (Nozick)", "No. Truth, real relationships and achievement are good in themselves (objective list theory)"] },
  { q: "Searle's Chinese Room: could a computer that perfectly imitates human conversation genuinely understand and feel, or only simulate it?", tag: 'sc', opts: ["Genuinely. Functionalism: a mind is what a system does, not what it's made of", "Probably, if it reproduced the brain's causal workings closely enough", "Only simulate. Running a program is shuffling symbols, which is not understanding (John Searle)", "Only simulate. Real consciousness needs a soul or something beyond matter that no machine can have"] },
  { q: "The hard problem of consciousness (David Chalmers): why does brain activity feel like anything from the inside, like the redness of red?", tag: 'sc', opts: ["It isn't a real problem. Once the brain's functions are explained, nothing is left over (Daniel Dennett)", "It is hard, but neuroscience will eventually solve it in physical terms", "It shows conscious experience is something extra, beyond the physical facts (Chalmers, Frank Jackson's Mary)", "It shows consciousness is fundamental, more basic than matter itself (idealism, panpsychism)"] },
  { q: "The Ship of Theseus: every plank of a ship is replaced, one by one, until none of the original is left. Is it still the same ship?", tag: 'sc', opts: ["Yes. Identity follows continuity of form and function over time", "It depends on our purposes. 'Same ship' is a matter of convention, not fact", "No. Identity follows the original matter, so it is a new ship", "There is no fact of the matter. The puzzle shows our concept of identity is vague"] },
  { q: "Nick Bostrom's simulation argument: if advanced civilisations run vast numbers of simulated minds, most minds like ours would be simulated. Are we probably living in a simulation?", tag: 'sc', opts: ["No. It is untestable speculation, so there is no reason to take it seriously", "Unlikely. Its premises are doubtful and there is no evidence for it", "Possibly. The argument is hard to refute, so I can't rule it out", "Probably. If its premises hold, the odds favour it"] },
  { q: "Benjamin Libet's experiments: the brain starts preparing a movement before people feel they have decided to move. What does this show about free will?", tag: 'sc', opts: ["Little. The experiments measured trivial urges, not real decisions, and we can still veto them", "That choices have unconscious roots, but freedom as compatibilists understand it survives", "That most of our decisions are made before we become aware of them", "That free will is an illusion: the feeling of choosing comes after the brain has decided (Daniel Wegner)"] },
  { q: "Moral luck (Thomas Nagel): two equally reckless drunk drivers; one kills a child by chance, the other gets home safely. Is the first more to blame?", tag: 'sc', opts: ["Yes. What actually happens matters morally, not just what we intended", "Somewhat. Outcomes carry some moral weight, though the recklessness is the core wrong", "No. Only what is in our control can be judged, so they are equally to blame (Kant)", "The case shows blame itself is confused: neither controlled what made them who they are"] },
  { q: "Karl Popper's paradox of tolerance: should a tolerant society tolerate movements that would destroy tolerance?", tag: 'sc', opts: ["Yes. Freedom of speech must apply to everyone, as a matter of principle", "Mostly, until they pose a real and present danger (John Rawls)", "No. Unlimited tolerance leads to the end of tolerance, so a free society may suppress them (Popper)", "There is no neutral answer. What counts as tolerance is set by whoever holds power (Herbert Marcuse)"] },
  { q: "The moral status of animals: is it wrong to make animals suffer for human benefit, such as food or medical research?", tag: 'sc', opts: ["Yes. Animals have rights, and using them merely as means is wrong whatever the gains (Tom Regan)", "Their suffering counts as much as ours, so it is wrong unless the benefit is truly huge (Peter Singer)", "Their suffering counts, but human benefits can outweigh it if it is kept to a minimum (animal welfarism)", "Animals lack moral standing of their own; we only have duties about them, not to them (Kant)"] },
  { q: "Moral progress: when past societies accepted slavery, were they mistaken about a moral truth?", tag: 'sc', opts: ["Yes. Moral truths are timeless, and they were simply wrong", "Yes, and moral progress is the slow discovery of more of the truth", "Only by our standards. Judged by the standards of their own time, they were not", "The question has no answer. Morality is whatever a society accepts"] },
  { q: "Philosophy of mathematics: do numbers exist, and is mathematics discovered or invented?", tag: 'sc', opts: ["Platonism: numbers are real abstract objects, existing independently of us, and we discover mathematics", "Mathematics describes real structures in the world, which reason discovers (structuralism, Aristotle)", "Formalism: mathematics is a game of symbols and rules that happens to be useful", "Constructivism: mathematics is a human invention, shaped by our language and culture"] },
  { q: "Occam's razor: do not multiply entities beyond necessity. When two theories fit the evidence equally well, should we believe the simpler one?", tag: 'sc', opts: ["Yes, always. Simplicity is a mark of truth", "Usually, as a sound rule of method, though not a guarantee", "No. Reality may be complicated; fit with everything else we know matters more", "Neither, until further evidence decides between them"] },
  { q: "Hume on miracles: a wise person proportions belief to the evidence, so testimony to a miracle should almost never be believed. Is he right?", tag: 'sc', opts: ["Yes. It is always more likely the witness is mistaken than that a law of nature was broken", "Mostly, though strong enough testimony could in principle establish a miracle", "No. Honest, sober witnesses deserve belief even about the extraordinary (Thomas Reid's principle of credulity)", "No. Miracles are possible, and refusing all testimony to them is dogmatic naturalism"] },
  { q: "Metaphysical naturalism: is the natural world, the world science studies, all there is?", tag: 'sc', opts: ["Yes. Everything that exists is part of nature and open to science", "Probably, though science is unfinished, so I can't be certain", "Probably not. Some realities, such as minds or values, may lie beyond science", "No. There is a spiritual or supernatural reality beyond nature"] },
  { q: "Leibniz asked: why is there something rather than nothing?", tag: 'sc', opts: ["Because a necessary being, God, is the cause of everything that exists (the cosmological argument)", "There is a deeper reason in reality, even if we can't grasp it (the principle of sufficient reason)", "There is no reason. The universe is simply a brute fact (Bertrand Russell)", "The question may be meaningless, since it asks for a cause outside all causes (Wittgenstein)"] },
  { q: "The meaning of life: does human life have meaning, and where would it come from?", tag: 'sc', opts: ["Yes, given by God or by the purpose built into the universe", "Yes, objectively, in things truly worth doing, such as love, knowledge and excellence (Aristotle, Susan Wolf)", "Not in itself, but we create meaning through our own choices (existentialism, Sartre)", "No. Life is meaningless, and the search for meaning is in vain (nihilism)"] },
  { q: "Epicurus argued that death is nothing to us: where death is, we are not. Is death bad for the person who dies?", tag: 'sc', opts: ["Not if there is an afterlife. Death is a passage, not an end", "Yes. Death deprives us of all the good things we would have had (the deprivation account, Thomas Nagel)", "No. Epicurus is right: once dead, there is no one left to be harmed", "No, and fearing it is irrational: it is just the end of a physical process (Lucretius)"] },
  { q: "John Rawls' veil of ignorance: you choose the rules for a society without knowing what place you will have in it. Which principle would you choose?", tag: 'sc', opts: ["Equal basic liberties for everyone, which no gain in welfare can override (Rawls' first principle)", "Equal liberties first, then allow inequalities only if they benefit the worst off (the difference principle)", "Whatever maximises average happiness, betting on the odds (John Harsanyi's utilitarianism)", "No abstract principle; rely on what has actually worked in real societies (Burke, Hayek)"] },
  { q: "Chesterton's fence: don't take down a fence until you know why it was put up. How much authority should tradition have?", tag: 'sc', opts: ["A great deal. Traditions carry the wisdom of generations, which reason alone can't replace (Edmund Burke)", "Real weight. There is probably a reason we can't see, so change should be cautious (Michael Oakeshott)", "Some, but a tradition has to justify itself by its results", "None in itself. Only reason and evidence count, and age proves nothing (Bentham, Thomas Paine)"] },
  { q: "Sartre said we are 'condemned to be free': whatever our circumstances, we are wholly responsible for what we make of ourselves. Is he right?", tag: 'sc', opts: ["Yes. Circumstances limit our options, but they never choose for us (existentialism)", "Largely. Circumstances matter, but we remain the authors of our choices", "Largely not. Upbringing, class and genes shape most of what we do (Marx, social determinism)", "No. Our choices are entirely the product of causes we didn't choose (hard determinism)"] },
  { q: "When an argument that seems valid, from premises that seem true, leads to a conclusion that seems plainly false, what should we do?", tag: 'sc', opts: ["Accept the conclusion. If the premises are true and the logic valid, intuition must give way", "Look for the faulty premise, but accept the conclusion if none can be found", "Reject a premise. We can be more certain the conclusion is false than that the premises are true (G.E. Moore)", "Distrust clever arguments in general; common sense is a better guide than philosophical reasoning"] },
);
